from candidate import vowels_count
import pytest
from unittest.mock import patch

@pytest.mark.parametrize("input_string, expected", [
    ("abcde", 2),
    ("ACEDY", 3),
    ("a", 1),
    ("a", 1),
    ("a", 1),
    ("a", 1),
    ("aeiou", 5),
    ("AEIOU", 5),
    ("aeiouy", 6),
    ("aeiouY", 6),
    ("aeiouY", 6),
    ("", 0),
    ("abcYd", 3),
    ("aYb", 2),
])
def test_vowels_count_normal_cases(input_string, expected):
    assert vowels_count(input_string) == expected

